/**
 * pyrepr.mjs — CPython-compatible `repr()` rendering.
 *
 * Only the subset needed to reproduce interpreter-level diagnostics
 * (notably `KeyError: 'z'`) is implemented, but the string rules follow
 * CPython's `unicode_repr` faithfully: quote selection, backslash
 * escaping and \xNN / \uNNNN escapes for non-printable code points.
 */

const SHORT_ESCAPES = Object.assign(Object.create(null), {
  '\\': '\\\\',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
});

/**
 * CPython prefers single quotes, but switches to double quotes when the
 * string contains a single quote and no double quote -- that way the
 * quote character itself never needs escaping.
 */
function chooseQuote(s) {
  return s.includes("'") && !s.includes('"') ? '"' : "'";
}

/** Code points CPython renders as an escape rather than literally. */
function isNonPrintable(cp) {
  if (cp < 0x20 || cp === 0x7f) return true;
  // C1 controls plus the Unicode separator/other categories CPython escapes.
  if (cp >= 0x80 && cp <= 0xa0) return true;
  return cp === 0xad;
}

function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

export function reprString(s) {
  const quote = chooseQuote(s);
  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === quote) out += '\\' + ch;
    else if (SHORT_ESCAPES[ch] !== undefined) out += SHORT_ESCAPES[ch];
    else if (isNonPrintable(cp)) out += escapeCodePoint(cp);
    else out += ch;
  }
  return out + quote;
}

export function reprNumber(n) {
  if (Number.isNaN(n)) return 'nan';
  if (n === Infinity) return 'inf';
  if (n === -Infinity) return '-inf';
  if (Number.isInteger(n) && Object.is(n, Math.trunc(n))) return String(n);
  return String(n);
}

export function repr(value) {
  if (value === null) return 'None';
  if (value === undefined) return 'None';
  switch (typeof value) {
    case 'string':
      return reprString(value);
    case 'number':
      return reprNumber(value);
    case 'bigint':
      return value.toString();
    case 'boolean':
      return value ? 'True' : 'False';
    default:
      break;
  }
  if (Array.isArray(value)) {
    // Rendered tuple-style: that is how bidict surfaces composite keys.
    if (value.length === 1) return '(' + repr(value[0]) + ',)';
    return '(' + value.map(repr).join(', ') + ')';
  }
  if (typeof value.__repr__ === 'function') return value.__repr__();
  return String(value);
}

