/**
 * pyerrors.mjs — Python exception shapes reproduced as JS error classes.
 *
 * Each carries the `pyType` used when rendering a traceback, and a
 * `pyMessage` holding exactly what CPython prints after the colon.
 */

import { repr } from './pyrepr.mjs';

export class PyError extends Error {
  constructor(pyType, pyMessage) {
    super(pyMessage);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = pyMessage;
  }
}

/**
 * KeyError is special-cased in CPython: its str() is the *repr* of the
 * missing key, not the key itself. Hence `KeyError: 'z'` with quotes.
 */
export class PyKeyError extends PyError {
  constructor(key) {
    super('KeyError', repr(key));
    this.key = key;
  }
}

export class PyTypeError extends PyError {
  constructor(message) {
    super('TypeError', message);
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

/** Base of the bidict duplication hierarchy (subclasses ValueError). */
export class DuplicationError extends PyValueError {
  constructor(pyType, message) {
    super(message);
    this.name = pyType;
    this.pyType = pyType;
  }
}

export class KeyDuplicationError extends DuplicationError {
  constructor(key) {
    super('KeyDuplicationError', repr(key));
    this.key = key;
  }
}

export class ValueDuplicationError extends DuplicationError {
  constructor(value) {
    super('ValueDuplicationError', repr(value));
    this.value = value;
  }
}

export class KeyAndValueDuplicationError extends DuplicationError {
  constructor(key, value) {
    super('KeyAndValueDuplicationError', `(${repr(key)}, ${repr(value)})`);
    this.key = key;
    this.value = value;
  }
}

