/**
 * hashindex.mjs — a Python-`dict`-like index built on null-prototype
 * objects and parallel arrays.
 *
 * Deliberately implemented without any built-in keyed-collection type:
 * lookup goes through a type-tagged string encoding of each key, and
 * insertion order is preserved by an append-only slot list (matching
 * CPython dict ordering since 3.7).
 */

import { PyTypeError } from './pyerrors.mjs';
import { repr } from './pyrepr.mjs';

const TOMBSTONE = Symbol('deleted');

/**
 * Encode a key into a string that collides exactly when Python's
 * hash/eq would. Notably Python treats `True == 1` and `1 == 1.0`,
 * so booleans and integral floats fold into the numeric namespace.
 */
export function encodeKey(key) {
  if (key === null || key === undefined) return 'N';
  switch (typeof key) {
    case 'string':
      return 's' + key;
    case 'boolean':
      return 'n' + (key ? '1' : '0');
    case 'bigint':
      return 'n' + key.toString();
    case 'number': {
      if (Number.isNaN(key)) return 'f:nan';
      if (Object.is(key, -0)) return 'n0';
      if (Number.isInteger(key)) return 'n' + key.toString();
      return 'f' + key.toString();
    }
    default:
      break;
  }
  if (Array.isArray(key)) {
    // Tuple-like: hashable only when every element is.
    return 't(' + key.map((el) => encodeKey(el).replace(/[\\;]/g, '\\$&')).join(';') + ')';
  }
  throw new PyTypeError(`unhashable type: ${repr(String(typeof key))}`);
}

export class HashIndex {
  constructor() {
    /** encoded key -> slot position in the entry arrays */
    this._slots = Object.create(null);
    this._keys = [];
    this._values = [];
    this._size = 0;
  }

  get size() {
    return this._size;
  }

  has(key) {
    return this._slots[encodeKey(key)] !== undefined;
  }

  /** Returns the stored value, or `fallback` when absent. */
  get(key, fallback = undefined) {
    const slot = this._slots[encodeKey(key)];
    return slot === undefined ? fallback : this._values[slot];
  }

  /**
   * Insert or overwrite. Re-assigning an existing key keeps its original
   * position, exactly like CPython dict.
   */
  set(key, value) {
    const enc = encodeKey(key);
    const slot = this._slots[enc];
    if (slot !== undefined) {
      this._values[slot] = value;
      return false;
    }
    this._slots[enc] = this._keys.length;
    this._keys.push(key);
    this._values.push(value);
    this._size += 1;
    return true;
  }

  delete(key) {
    const enc = encodeKey(key);
    const slot = this._slots[enc];
    if (slot === undefined) return false;
    delete this._slots[enc];
    this._keys[slot] = TOMBSTONE;
    this._values[slot] = TOMBSTONE;
    this._size -= 1;
    this._compactIfSparse();
    return true;
  }

  clear() {
    this._slots = Object.create(null);
    this._keys = [];
    this._values = [];
    this._size = 0;
  }

  /** Reclaim tombstones once they dominate, keeping iteration linear. */
  _compactIfSparse() {
    if (this._keys.length < 16 || this._size * 2 > this._keys.length) return;
    const keys = [];
    const values = [];
    const slots = Object.create(null);
    for (let i = 0; i < this._keys.length; i += 1) {
      if (this._keys[i] === TOMBSTONE) continue;
      slots[encodeKey(this._keys[i])] = keys.length;
      keys.push(this._keys[i]);
      values.push(this._values[i]);
    }
    this._slots = slots;
    this._keys = keys;
    this._values = values;
  }

  *entries() {
    for (let i = 0; i < this._keys.length; i += 1) {
      if (this._keys[i] === TOMBSTONE) continue;
      yield [this._keys[i], this._values[i]];
    }
  }

  *keys() {
    for (const [k] of this.entries()) yield k;
  }

  *values() {
    for (const [, v] of this.entries()) yield v;
  }

  [Symbol.iterator]() {
    return this.entries();
  }
}

