/**
 * bidict.mjs — a bidirectional dictionary reimplemented from observed
 * interface behaviour.
 *
 * A bidict maintains a one-to-one correspondence: every key maps to a
 * unique value and every value back to a unique key. The `inverse` view
 * shares storage with its forward bidict, so mutations are visible from
 * both sides immediately.
 */

import { HashIndex } from './hashindex.mjs';
import {
  PyKeyError,
  KeyDuplicationError,
  ValueDuplicationError,
  KeyAndValueDuplicationError,
} from './pyerrors.mjs';
import { repr } from './pyrepr.mjs';

/** Duplication policies, mirroring bidict's ON_DUP constants. */
export const RAISE = 'RAISE';
export const DROP_OLD = 'DROP_OLD';
export const DROP_NEW = 'DROP_NEW';

/** Default for __init__ / update / __setitem__: keys overwrite, values raise. */
export const ON_DUP_DEFAULT = { key: DROP_OLD, val: RAISE };
/** Default for put / putall. */
export const ON_DUP_RAISE = { key: RAISE, val: RAISE };
/** Default for forceput / forceupdate. */
export const ON_DUP_DROP_OLD = { key: DROP_OLD, val: DROP_OLD };

/**
 * The source frame bidict raises from on a failed lookup. Surfaced so the
 * host program can render a faithful traceback.
 */
export const GETITEM_FRAME = Object.freeze({
  file: 'bidict/_base.py',
  line: 524,
  func: '__getitem__',
});

/** Normalize the many shapes accepted for initial contents into pairs. */
function toPairs(source) {
  if (source === null || source === undefined) return [];
  if (source instanceof BidictBase) return [...source.entries()];
  if (source instanceof HashIndex) return [...source.entries()];
  if (Array.isArray(source)) return source.map(([k, v]) => [k, v]);
  if (typeof source[Symbol.iterator] === 'function') {
    return [...source].map(([k, v]) => [k, v]);
  }
  if (typeof source === 'object') {
    return Object.keys(source).map((k) => [k, source[k]]);
  }
  return [];
}

export class BidictBase {
  /**
   * @param {*} source        initial contents (object, pair array, or bidict)
   * @param {object} [opts]
   * @param {object} [opts._fwd] internal: shared forward index
   * @param {object} [opts._inv] internal: shared inverse index
   */
  constructor(source = null, opts = {}) {
    if (opts._fwd && opts._inv) {
      // Building the paired inverse view over already-shared storage.
      this._fwd = opts._fwd;
      this._inv = opts._inv;
      this._inverse = opts._owner;
      return;
    }
    this._fwd = new HashIndex();
    this._inv = new HashIndex();
    this._inverse = new this.constructor(null, {
      _fwd: this._inv,
      _inv: this._fwd,
      _owner: this,
    });
    this._update(toPairs(source), ON_DUP_DEFAULT);
  }

  get inverse() {
    return this._inverse;
  }

  /** Long-standing alias for `inverse`. */
  get inv() {
    return this._inverse;
  }

  get size() {
    return this._fwd.size;
  }

  /** Python's `len(b)`. */
  __len__() {
    return this._fwd.size;
  }

  /**
   * `b[key]`. Raises KeyError -- carrying bidict's own frame -- when the
   * key is absent, matching the interpreter's behaviour.
   */
  getItem(key) {
    if (!this._fwd.has(key)) {
      const err = new PyKeyError(key);
      err.pyFrames = [GETITEM_FRAME];
      throw err;
    }
    return this._fwd.get(key);
  }

  /** Non-raising lookup. */
  get(key, fallback = undefined) {
    return this._fwd.has(key) ? this._fwd.get(key) : fallback;
  }

  has(key) {
    return this._fwd.has(key);
  }

  /** `b[key] = value` -- overwrites duplicate keys, rejects duplicate values. */
  setItem(key, value) {
    this._write(key, value, ON_DUP_DEFAULT);
  }

  /** Strict insert: any duplication on either side raises. */
  put(key, value, onDup = ON_DUP_RAISE) {
    this._write(key, value, onDup);
  }

  /** Unconditional insert: displaces whatever collides. */
  forceput(key, value) {
    this._write(key, value, ON_DUP_DROP_OLD);
  }

  delete(key) {
    if (!this._fwd.has(key)) {
      const err = new PyKeyError(key);
      err.pyFrames = [GETITEM_FRAME];
      throw err;
    }
    const value = this._fwd.get(key);
    this._fwd.delete(key);
    this._inv.delete(value);
  }

  update(source) {
    this._update(toPairs(source), ON_DUP_DEFAULT);
  }

  forceupdate(source) {
    this._update(toPairs(source), ON_DUP_DROP_OLD);
  }

  clear() {
    this._fwd.clear();
    this._inv.clear();
  }

  /**
   * Apply a batch atomically: bidict validates the whole batch before
   * committing, so a mid-batch failure leaves the mapping untouched.
   */
  _update(pairs, onDup) {
    if (pairs.length === 0) return;
    const snapshot = [...this._fwd.entries()];
    try {
      for (const [key, value] of pairs) this._write(key, value, onDup);
    } catch (err) {
      this._fwd.clear();
      this._inv.clear();
      for (const [k, v] of snapshot) {
        this._fwd.set(k, v);
        this._inv.set(v, k);
      }
      throw err;
    }
  }

  /** Single-pair write honouring the duplication policy. */
  _write(key, value, onDup) {
    const keyDup = this._fwd.has(key);
    const valDup = this._inv.has(value);

    // An existing key already bound to this exact value is a no-op, not a
    // duplication -- bidict treats the pair as already present.
    if (keyDup && valDup && this._fwd.get(key) === value) return;

    if (keyDup && valDup) {
      if (onDup.key === RAISE || onDup.val === RAISE) {
        throw new KeyAndValueDuplicationError(key, value);
      }
      if (onDup.key === DROP_NEW || onDup.val === DROP_NEW) return;
    } else if (keyDup) {
      if (onDup.key === RAISE) throw new KeyDuplicationError(key);
      if (onDup.key === DROP_NEW) return;
    } else if (valDup) {
      if (onDup.val === RAISE) throw new ValueDuplicationError(value);
      if (onDup.val === DROP_NEW) return;
    }

    // Detach whatever the incoming pair displaces on either side.
    if (keyDup) this._inv.delete(this._fwd.get(key));
    if (valDup) this._fwd.delete(this._inv.get(value));

    this._fwd.set(key, value);
    this._inv.set(value, key);
  }

  keys() {
    return this._fwd.keys();
  }

  values() {
    return this._fwd.values();
  }

  entries() {
    return this._fwd.entries();
  }

  [Symbol.iterator]() {
    return this._fwd.entries();
  }

  forEach(fn, thisArg = undefined) {
    for (const [k, v] of this.entries()) fn.call(thisArg, v, k, this);
  }

