   * Apply a batch atomically: bidict validates the whole batch before
   * committing, so a mid-batch failure leaves the mapping untouched.
   */
  _update(pairs, onDup) {
    if (pairs.length === 0) return;
    const snapshot = [...this._fwd.entries()];
    try {
      for (const [key, value] of pairs) this._write(key, value, onDup);
    } catch (err) {
      this._fwd.clear();
      this._inv.clear();
      for (const [k, v] of snapshot) {
