    return this._fwd.values();
  }

  entries() {
    return this._fwd.entries();
  }

  [Symbol.iterator]() {
    return this._fwd.entries();
  }

  forEach(fn, thisArg = undefined) {
    for (const [k, v] of this.entries()) fn.call(thisArg, v, k, this);
