  __repr__() {
    const body = [...this.entries()]
      .map(([k, v]) => `${repr(k)}: ${repr(v)}`)
      .join(', ');
    return `${this.constructor.pyName}({${body}})`;
  }

  toString() {
    return this.__repr__();
  }
}

