/**
 * argparse.mjs — the subset of CPython's `argparse` needed to parse this
 * program's command line identically.
 *
 * Reproduces: long-option abbreviation, `--opt=value` and `--opt value`
 * forms, the option-vs-argument token classification (including the
 * negative-number rule), required-argument reporting, `unrecognized
 * arguments` collection, the auto `-h/--help` action, the exact usage and
 * help layout, and the exit codes (0 for help, 2 for a parse error).
 */

const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

/** A single registered option. */
class Action {
  constructor({ optionStrings, dest, required = false, metavar = null, help = null, isHelp = false }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.required = required;
    this.metavar = metavar;
    this.help = help;
    this.isHelp = isHelp;
    this.nargs = isHelp ? 0 : 1;
  }

  /** How argparse names this action inside error messages. */
  get name() {
    return this.optionStrings.join('/');
  }

  /** `-h, --help` or `--key KEY` as shown in the help body. */
  formatInvocation() {
    if (this.nargs === 0) return this.optionStrings.join(', ');
    const arg = this.metavar || this.dest.toUpperCase();
    return this.optionStrings.map((opt) => `${opt} ${arg}`).join(', ');
  }

  /** `[-h]` or `--key KEY` as shown in the usage line. */
  formatUsage() {
    const opt = this.optionStrings[0];
    const body = this.nargs === 0 ? opt : `${opt} ${this.metavar || this.dest.toUpperCase()}`;
    return this.required ? body : `[${body}]`;
  }
}

/** Raised internally to unwind to the parser's top-level error handler. */
class ArgumentError extends Error {
  constructor(action, message) {
    super(message);
    this.actionName = action ? action.name : null;
  }
}

export class ArgumentParser {
  /**
   * @param {object} [opts]
   * @param {string} [opts.prog]    program name used in usage/errors
   * @param {boolean} [opts.addHelp] register -h/--help (default true)
   * @param {object} [opts.io]      injectable stdout/stderr/exit for testing
   */
  constructor({ prog = null, addHelp = true, io = null } = {}) {
    this.prog = prog || defaultProg();
    this._actions = [];
    this._io = io || {
      stdout: (s) => process.stdout.write(s),
      stderr: (s) => process.stderr.write(s),
      exit: (code) => process.exit(code),
    };
    if (addHelp) {
      this._actions.push(
        new Action({
          optionStrings: ['-h', '--help'],
          dest: 'help',
          isHelp: true,
          help: 'show this help message and exit',
        }),
      );
    }
  }

  /**
   * Register an option. Mirrors `parser.add_argument('--key', type=str,
   * required=True)`; `type` is accepted for parity but every value arrives
   * as a string, which is what `type=str` yields.
   */
  addArgument(optionString, { required = false, metavar = null, help = null, dest = null } = {}) {
    const strings = Array.isArray(optionString) ? optionString : [optionString];
    const long = strings.find((s) => s.startsWith('--')) || strings[0];
    const action = new Action({
      optionStrings: strings,
      dest: dest || long.replace(/^-+/, '').replace(/-/g, '_'),
      required,
      metavar,
      help,
    });
