   * argparse's rule: a token is an option if it starts with a prefix
   * character and is neither a lone `-`, a negative number (when no
   * option looks like one), nor something containing a space.
   */
  _isOptionToken(token) {
    if (!token || token[0] !== '-') return false;
    if (token === '-') return false;
    if (token === '--') return true;
    if (NEGATIVE_NUMBER_RE.test(token) && !this._hasNegativeNumberOptions()) return false;
    if (token.includes(' ')) return false;
    return true;
  }

  _hasNegativeNumberOptions() {
    return this._actions.some((a) => a.optionStrings.some((s) => NEGATIVE_NUMBER_RE.test(s)));
  }

  /**
   * Resolve an option string, allowing unambiguous abbreviation of long
   * options. Returns null when nothing matches (caller treats it as extra).
   */
  _matchOption(name) {
    for (const action of this._actions) {
      if (action.optionStrings.includes(name)) return action;
    }
    if (!name.startsWith('--')) return null;
    const matches = [];
    for (const action of this._actions) {
      for (const opt of action.optionStrings) {
        if (opt.startsWith(name)) matches.push([opt, action]);
      }
    }
    if (matches.length === 1) return matches[0][1];
    if (matches.length > 1) {
      const options = matches.map(([opt]) => opt).join(', ');
