  parseKnownArgs(argv = process.argv.slice(2)) {
    const namespace = Object.create(null);
    for (const action of this._actions) {
      if (!action.isHelp) namespace[action.dest] = null;
    }

    const extras = [];
    const seen = new Set();

    try {
      let i = 0;
      let sawSeparator = false;
      while (i < argv.length) {
        const token = argv[i];

        if (token === '--' && !sawSeparator) {
          // Everything after the first `--` is positional. This parser
          // defines no positionals, so the separator and remainder are
          // reported as unrecognized -- matching observed behaviour.
          sawSeparator = true;
          extras.push(token);
          i += 1;
          continue;
        }

        if (sawSeparator || !this._isOptionToken(token)) {
          extras.push(token);
          i += 1;
          continue;
        }

        // Split the explicit `--opt=value` form.
        let name = token;
        let explicitValue = null;
        const eq = token.indexOf('=');
        if (token.startsWith('--') && eq !== -1) {
          name = token.slice(0, eq);
          explicitValue = token.slice(eq + 1);
        }

        const action = this._matchOption(name);
        if (action === null) {
          extras.push(token);
          i += 1;
          continue;
        }

        if (action.isHelp) {
          if (explicitValue !== null) {
            throw new ArgumentError(action, `ignored explicit argument '${explicitValue}'`);
          }
          this.printHelp();
          this._io.exit(0);
          return [namespace, extras];
        }

        let value;
        if (explicitValue !== null) {
          value = explicitValue;
        } else {
          const next = argv[i + 1];
          if (next === undefined || this._isOptionToken(next)) {
            throw new ArgumentError(action, 'expected one argument');
          }
          value = next;
          i += 1;
        }

        // Later occurrences overwrite earlier ones.
        namespace[action.dest] = value;
        seen.add(action);
        i += 1;
      }
    } catch (err) {
      if (!(err instanceof ArgumentError)) throw err;
      const prefix = err.actionName ? `argument ${err.actionName}: ` : '';
      this.error(prefix + err.message);
    }

    const missing = this._actions.filter((a) => !a.isHelp && a.required && !seen.has(a));
    if (missing.length > 0) {
      const names = missing.map((a) => a.name).join(', ');
      this.error(`the following arguments are required: ${names}`);
    }

    return [namespace, extras];
  }

  // ---- formatting ------------------------------------------------------

  formatUsage() {
    const parts = this._actions.map((a) => a.formatUsage());
    return `usage: ${this.prog}${parts.length ? ' ' + parts.join(' ') : ''}\n`;
  }

  formatHelp() {
    let out = this.formatUsage();
    out += '\noptions:\n';

    // argparse aligns help text at `min(maxInvocation + indent + 2, 24)`.
    const invocations = this._actions.map((a) => a.formatInvocation());
    const maxLen = invocations.reduce((m, s) => Math.max(m, s.length + 2), 0);
    const helpPosition = Math.min(maxLen + 2, 24);

    this._actions.forEach((action, idx) => {
      const invocation = invocations[idx];
      if (!action.help) {
        out += `  ${invocation}\n`;
        return;
      }
      if (invocation.length + 2 <= helpPosition - 2) {
        out += `  ${invocation}`.padEnd(helpPosition, ' ') + `${action.help}\n`;
      } else {
        out += `  ${invocation}\n${' '.repeat(helpPosition)}${action.help}\n`;
      }
    });
    return out;
  }

  printUsage() {
    this._io.stdout(this.formatUsage());
  }

  printHelp() {
    this._io.stdout(this.formatHelp());
  }

  /** Print usage + message to stderr and exit 2, exactly like argparse. */
  error(message) {
    this._io.stderr(this.formatUsage());
    this._io.stderr(`${this.prog}: error: ${message}\n`);
    this._io.exit(2);
  }
}

