    const invocations = this._actions.map((a) => a.formatInvocation());
    const maxLen = invocations.reduce((m, s) => Math.max(m, s.length + 2), 0);
    const helpPosition = Math.min(maxLen + 2, 24);

    this._actions.forEach((action, idx) => {
      const invocation = invocations[idx];
      if (!action.help) {
        out += `  ${invocation}\n`;
        return;
      }
