/**
 * test2.mjs — Node.js port of test2.py.
 *
 *   import argparse
 *   from bidict import bidict
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--key', type=str, required=True)
 *   parser.add_argument('--val', type=str, required=True)
 *   args = parser.parse_args()
 *
 *   # 创建双向字典并访问值
 *   b = bidict({'a': 1, 'b': 2})
 *   result = b[args.key]
 *   print(result)
 */

import { ArgumentParser } from './lib/argparse.mjs';
import { bidict } from './lib/bidict.mjs';
import { PyError } from './lib/pyerrors.mjs';
import { abortWithTraceback, pyPrint } from './lib/pyruntime.mjs';

/**
 * The frozen build reports itself as `test2_executable` in usage and error
 * lines, so the port names itself the same way for byte-identical output.
 */
const PROG = 'test2_executable';
const SCRIPT = 'test2';

/** The `b[args.key]` frame, as the interpreter renders it. */
const MAIN_FRAME = {
  file: 'test2.py',
  line: 11,
  func: '<module>',
  source: 'result = b[args.key]',
  anchor: '             ~^^^^^^^^^^',
};

export function main(argv = process.argv.slice(2)) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--key', { required: true });
  parser.addArgument('--val', { required: true });
  const args = parser.parseArgs(argv);

  // 创建双向字典并访问值
  const b = bidict({ a: 1, b: 2 });

  let result;
  try {
    result = b.getItem(args.key);
  } catch (err) {
    if (!(err instanceof PyError)) throw err;
    // Prepend the module-level frame to whatever bidict raised from.
    abortWithTraceback([MAIN_FRAME, ...(err.pyFrames || [])], err, SCRIPT);
    return;
  }

  pyPrint(result);
}

main();

