import { bidict } from '/output/lib/bidict.mjs';
import { ValueDuplicationError, KeyDuplicationError, PyKeyError } from '/output/lib/pyerrors.mjs';

const b = bidict({ a: 1, b: 2 });
console.log('fwd:', b.getItem('a'), b.getItem('b'));
console.log('inverse:', b.inverse.getItem(1), b.inv.getItem(2));
console.log('repr:', String(b));
console.log('size:', b.size, '| entries:', JSON.stringify([...b.entries()]));

// inverse is paired both ways
console.log('inverse.inverse === b:', b.inverse.inverse === b);

// duplicate value rejected on __setitem__ (bidict default val=RAISE)
try { b.setItem('c', 1); console.log('BAD: no raise'); }
catch (e) { console.log('dup value ->', e.constructor.name, e.pyMessage); }

// duplicate key overwrites, and the inverse follows
b.setItem('a', 9);
console.log('after a=9:', b.getItem('a'), '| inv has 1:', b.inverse.has(1), '| inv[9]:', b.inverse.getItem(9));

// put() is strict on keys too
try { b.put('b', 42); } catch (e) { console.log('put dup key ->', e.constructor.name, e.pyMessage); }
// forceput displaces
b.forceput('b', 42);
console.log('after forceput b=42:', b.getItem('b'), '| inv[42]:', b.inverse.getItem(42));

// atomic update: failure leaves mapping untouched
const c = bidict({ x: 1, y: 2 });
try { c.update([['z', 3], ['w', 1]]); } catch (e) { console.log('atomic update ->', e.constructor.name); }
console.log('unchanged:', String(c));

// KeyError repr matches Python semantics
try { c.getItem('nope'); } catch (e) { console.log('KeyError pyMessage:', e.pyMessage, '| frames:', JSON.stringify(e.pyFrames)); }

// delete keeps both sides in sync
c.delete('x');
console.log('after delete x:', String(c), '| inv has 1:', c.inverse.has(1));

// Python key-identity nuance: True == 1
const d = bidict([[1, 'one']]);
console.log('d[true] (True==1):', d.getItem(true));
EOF
