/**
 * linecache.mjs — Python's `linecache` plus the 3.11+ traceback anchor
 * geometry.
 *
 * CPython does not embed source text in a traceback; it re-reads the file
 * named in the frame at render time, resolved against the current working
 * directory. A frozen executable therefore prints the offending source
 * line only when a file of that name happens to sit in the cwd, and prints
 * whatever that file currently holds -- behaviour this module reproduces
 * so the port matches from any directory.
 */

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';

/** Python's `str.strip()` whitespace set (ASCII subset, which is what applies here). */
const PY_WS = ' \t\n\r\v\f';

function isPySpace(ch) {
  return PY_WS.includes(ch);
}

function pyLStrip(s) {
  let i = 0;
  while (i < s.length && isPySpace(s[i])) i += 1;
  return s.slice(i);
}

function pyStrip(s) {
  let end = s.length;
  while (end > 0 && isPySpace(s[end - 1])) end -= 1;
  return pyLStrip(s.slice(0, end));
}

/**
 * Read line `lineno` (1-based) of `filename`, resolved against the cwd.
 * Returns null when the file is unreadable or too short -- the case where
 * CPython silently omits the source line.
 */
export function getLine(filename, lineno) {
  let text;
  try {
    text = readFileSync(resolve(process.cwd(), filename), 'utf8');
  } catch {
    return null;
  }
  const lines = text.split('\n');
  // A trailing newline does not start a new line in Python's readlines().
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop();
  if (lineno < 1 || lineno > lines.length) return null;
  return lines[lineno - 1].replace(/\r$/, '');
}

/**
 * Split a subscript segment into its value and `[...]` parts, which the
 * anchor line underlines with `~` and `^` respectively.
 */
function splitSubscript(segment) {
  const m = /^([A-Za-z_][\w.]*)(\[.*\])$/.exec(segment);
  return m ? { primary: m[1].length, secondary: m[2].length } : null;
}

/**
 * Render the source and anchor lines for a frame.
 *
 * @param {string} rawLine        line as it currently exists on disk
 * @param {number} colOffset      column of the failing sub-expression in
 *                                the original source line (0-based)
 * @param {number} endColOffset   exclusive end column
 * @returns {{source: string, anchor: string|null}|null}
 */
export function formatSourceLine(rawLine, colOffset = null, endColOffset = null) {
  const stripped = pyStrip(rawLine);
  if (stripped === '') return null;

  const source = `    ${stripped}`;
  if (colOffset === null || endColOffset === null) return { source, anchor: null };

  // Offsets are recorded against the original line, so shift by however
  // much leading whitespace the on-disk line actually has.
  const leading = rawLine.length - pyLStrip(rawLine).length;
  const start = colOffset - leading;
  const end = endColOffset - leading;
  if (start < 0 || end > stripped.length || end <= start) return { source, anchor: null };

  // An anchor spanning the whole line adds nothing, so CPython omits it.
  if (start === 0 && end === stripped.length) return { source, anchor: null };

  const segment = stripped.slice(start, end);
  const parts = splitSubscript(segment);
  const marks = parts
    ? '~'.repeat(parts.primary) + '^'.repeat(parts.secondary)
    : '^'.repeat(end - start);

  return { source, anchor: ' '.repeat(4 + start) + marks };
}

