toolUseResult.originalFile:
/**
 * pyruntime.mjs — reproduces CPython's unhandled-exception output and the
 * PyInstaller bootloader's trailing diagnostic.
 *
 * Frames are supplied by the caller because this runtime has no real
 * Python stack to walk; the frozen program's traceback is fixed by its
 * source, so the shape is data rather than something to introspect.
 */

/**
 * Render a traceback body.
 *
 * @param {Array<{file:string,line:number,func:string,source?:string,anchor?:string}>} frames
 *        outermost frame first, matching "most recent call last"
 * @param {{pyType:string, pyMessage:string}} error
 */
export function formatTraceback(frames, error) {
  let out = 'Traceback (most recent call last):\n';
  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.func}\n`;
    if (frame.source) {
      out += `    ${frame.source}\n`;
      // Python 3.11+ underlines the sub-expression that raised.
      if (frame.anchor) out += `${frame.anchor}\n`;
    }
  }
  const message = error.pyMessage;
  out += message === '' ? `${error.pyType}\n` : `${error.pyType}: ${message}\n`;
  return out;
}

/**
 * The PyInstaller bootloader appends this after a script dies, tagged with
 * the running process id.
 */
export function formatBootloaderError(scriptName) {
  return `[PYI-${process.pid}:ERROR] Failed to execute script '${scriptName}' due to unhandled exception!\n`;
}

/**
 * Print an unhandled Python-style exception the way the frozen executable
 * does -- traceback and bootloader notice on stderr -- and exit 1.
 */
export function abortWithTraceback(frames, error, scriptName, io = defaultIo()) {
  io.stderr(formatTraceback(frames, error));
  io.stderr(formatBootloaderError(scriptName));
  io.exit(1);
}

export function defaultIo() {
  return {
    stdout: (s) => process.stdout.write(s),
    stderr: (s) => process.stderr.write(s),
    exit: (code) => process.exit(code),
  };
}

/** Python's `print()`: str() of the value followed by a newline. */
export function pyPrint(value, io = defaultIo()) {
  io.stdout(`${pyStr(value)}\n`);
}

/** Python's `str()` for the scalar types this program prints. */
export function pyStr(value) {
  if (value === null || value === undefined) return 'None';
  if (typeof value === 'boolean') return value ? 'True' : 'False';
  if (typeof value === 'number') {
    if (Number.isNaN(value)) return 'nan';
    if (value === Infinity) return 'inf';
    if (value === -Infinity) return '-inf';
    return String(value);
  }
  return String(value);
}

